import "../css/DeliveryAddress.css";
export default function DeliveryAddress(props) {
    const deliveryAddress = props.userDetails && props.userDetails.deliveryAddress;
    return (
        <div className="deliveryAddressContainer">
            <h3>Delivery Address</h3>
            <span className="deliveryAddressDetails">
                {deliveryAddress && deliveryAddress.map((address, index) => (
                    <div key={index}>
                        <p>Street: {address.street}</p>
                        <p>City: {address.city}</p>
                        <p>State: {address.state}</p>
                        <p>Zip: {address.zip}</p>
                    </div>
                ))}
            </span>
            <p>{props.userDetails && props.userDetails.address ? `${props.userDetails.address.street}, ${props.userDetails.address.city}, ${props.userDetails.address.state}, ${props.userDetails.address.zip}` : 'N/A'}</p>
            <p>Phone: {props.userDetails && props.userDetails.phone ? props.userDetails.phone : 'N/A'}</p>
            <p>Email: {props.userDetails && props.userDetails.email ? props.userDetails.email : 'N/A'}</p>
        </div>
    );
}
